const items = $input.all();

function limpiarRespuesta(texto) {
  let respuesta = String(texto || "").trim();

  respuesta = respuesta
    .replace(/Espero que esta información te sea útil\.?/gi, "")
    .replace(/¿Tienes alguna otra pregunta\?/gi, "")
    .replace(/Tienes alguna otra pregunta\?/gi, "")
    .replace(/Estoy aquí para ayudarte\.?/gi, "")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();

  return respuesta || "No se generó una respuesta del agente.";
}

return items.map((item) => {
