const items = $input.all();
const rows = items.map((item) => item.json);

const clasificador = $("Code - Clasificar Intención").item.json;
const editFields = $("Edit Fields").item.json;

const preguntaOriginal =
  clasificador.pregunta_original ||
  editFields.pregunta_usuario ||
  "";

const preguntaNormalizada =
  clasificador.pregunta_normalizada ||
  "";

function numero(valor) {
  const n = Number(valor);
  if (Number.isNaN(n)) return 0;
  return n;
}

function dineroCOP(valor) {
  const n = Number(valor);
  if (Number.isNaN(n)) return "no disponible";

  return n.toLocaleString("es-CO", {
    style: "currency",
    currency: "COP",
    maximumFractionDigits: 0
  });
}

function detectarTipoHabitacion(pregunta) {
  if (pregunta.includes("suite") || pregunta.includes("suites")) return "suite";
  if (pregunta.includes("familiar") || pregunta.includes("familiares")) return "familiar";
  if (pregunta.includes("triple") || pregunta.includes("triples")) return "triple";
  if (pregunta.includes("doble") || pregunta.includes("dobles")) return "doble";

  if (
    pregunta.includes("sencilla") ||
    pregunta.includes("sencillas") ||
    pregunta.includes("individual") ||
    pregunta.includes("individuales")
  ) {
    return "sencilla";
  }

  return null;
}

const tipoSolicitado = detectarTipoHabitacion(preguntaNormalizada);

const totalHabitaciones = rows.reduce(
  (acc, row) => acc + numero(row.total_habitaciones),
  0
);

const totalDisponibles = rows.reduce(
  (acc, row) => acc + numero(row.disponibles),
  0
);

const totalOcupadas = rows.reduce(
  (acc, row) => acc + numero(row.ocupadas),
  0
);

const totalReservadas = rows.reduce(
  (acc, row) => acc + numero(row.reservadas),
  0
);

const totalMantenimiento = rows.reduce(
  (acc, row) => acc + numero(row.mantenimiento),
  0
);

let respuesta = "";

if (tipoSolicitado) {
  const habitacion = rows.find((row) => row.tipo_habitacion === tipoSolicitado);

  if (!habitacion) {
    respuesta = `No encontré información de disponibilidad para habitaciones tipo ${tipoSolicitado}.`;
  } else {
    respuesta =
      `Actualmente hay ${habitacion.disponibles} habitaciones tipo ${tipoSolicitado} disponibles ` +
      `de ${habitacion.total_habitaciones} registradas. ` +
      `También hay ${habitacion.ocupadas} ocupadas, ${habitacion.reservadas} reservadas ` +
      `y ${habitacion.mantenimiento} en mantenimiento. ` +
      `La capacidad máxima de este tipo de habitación es de ${habitacion.capacidad_maxima} personas. ` +
      `El precio simulado por noche está entre ${dineroCOP(habitacion.precio_minimo_cop)} ` +
      `y ${dineroCOP(habitacion.precio_maximo_cop)}.`;
  }
} else {
  const resumenTipos = rows
    .map((row) => {
      return `${row.tipo_habitacion}: ${row.disponibles} disponibles de ${row.total_habitaciones}`;
    })
    .join("; ");

  respuesta =
    `Actualmente el hotel tiene ${totalDisponibles} habitaciones disponibles ` +
    `de ${totalHabitaciones} habitaciones registradas. ` +
    `También hay ${totalOcupadas} ocupadas, ${totalReservadas} reservadas ` +
    `y ${totalMantenimiento} en mantenimiento. ` +
    `Resumen por tipo: ${resumenTipos}.`;
}

return [
  {
    json: {
      tipo_solicitud: "disponibilidad_habitaciones",
      pregunta_usuario: preguntaOriginal,
      pregunta_normalizada: preguntaNormalizada,
      nombre_hotel: editFields.nombre_hotel || "Hotel El Claustro de San Francisco",
      fuente: "Tabla habitaciones_demo en PostgreSQL",
      total_habitaciones: totalHabitaciones,
      total_disponibles: totalDisponibles,
      total_ocupadas: totalOcupadas,
      total_reservadas: totalReservadas,
      total_mantenimiento: totalMantenimiento,
      tipo_habitacion_consultado: tipoSolicitado || "general",
      detalle_disponibilidad: rows,
      respuesta_final: respuesta,
      estado: "disponibilidad_consultada",
      timestamp: new Date().toISOString()
    }
  }
];
